import{_ as s,a,c as t,ac as r}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · 单元 2 复习与自测 · 第25–33课","description":"L25–L48 原创练习和答案解析。","frontmatter":{"title":"第二册：实践与进步 · 单元 2 复习与自测 · 第25–33课","description":"L25–L48 原创练习和答案解析。","splitFrom":"life/english/new-concept/book-2/unit-02/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第二册：实践与进步 · 单元 2 复习与自测","summary":"L25–L48 原创练习和答案解析。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · 单元 2 复习与自测","link":"/life/english/new-concept/book-2/unit-02/review"},"next":{"text":"第二册：实践与进步 · 单元 2 复习与自测 · 第34–42课","link":"/life/english/new-concept/book-2/unit-02/review-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · 单元 2 复习与自测","link":"/life/english/new-concept/book-2/unit-02/review"},"next":{"text":"第二册：实践与进步 · 单元 2 复习与自测 · 第34–42课","link":"/life/english/new-concept/book-2/unit-02/review-part-02"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-02/review-part-01.md","filePath":"life/english/new-concept/book-2/unit-02/review-part-01.md"}'),o={name:"life/english/new-concept/book-2/unit-02/review-part-01.md"};function n(i,e,l,h,p,d){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="第二册-实践与进步-·-单元-2-复习与自测-·-第25–33课" tabindex="-1">第二册：实践与进步 · 单元 2 复习与自测 · 第25–33课 <a class="header-anchor" href="#第二册-实践与进步-·-单元-2-复习与自测-·-第25–33课" aria-label="Permalink to &quot;第二册：实践与进步 · 单元 2 复习与自测 · 第25–33课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-2/unit-02/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-2/unit-02/overview">单元导读</a> · <a href="/life/english/new-concept/book-2/unit-02/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-2/unit-02/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-2/unit-02/review">单元复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="第二册-实践与进步-·-单元-2-复习与自测" tabindex="-1">第二册：实践与进步 · 单元 2 复习与自测 <a class="header-anchor" href="#第二册-实践与进步-·-单元-2-复习与自测" aria-label="Permalink to &quot;第二册：实践与进步 · 单元 2 复习与自测 {#第二册-实践与进步-·-单元-2-复习与自测}&quot;">​</a></h2><p><a href="/life/english/new-concept/book-2/unit-02/overview">单元导读</a> · <a href="/life/english/new-concept/book-2/unit-02/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-2/unit-02/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-2/unit-02/review">单元复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-25-·-间接引语与视角转换" tabindex="-1">Lesson 25 · 间接引语与视角转换 <a class="header-anchor" href="#lesson-25-·-间接引语与视角转换" aria-label="Permalink to &quot;Lesson 25 · 间接引语与视角转换 {#lesson-25-·-间接引语与视角转换}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> I asked the driver where the bus stopped.</p><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1 {#练习-1}&quot;">​</a></h3><p>选语序：I asked where the bus stopped / where did the bus stop.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> where the bus stopped</p><p><strong>解析：</strong> 间接疑问句使用陈述语序。</p></details><p><strong>表达迁移：</strong> 转述一次问路过程，包含一个 where 间接问句和一次澄清。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I asked the driver where the bus stopped. He repeated the name of the street. Once he showed me the map, I understood.</p><p>第一句的组织方式：asked 带听者 the driver 和间接疑问从句；where 引导地点问题，从句不倒装。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：I asked where did it stop 错误；从句应为 where it stopped。</p></details><p><a href="/life/english/new-concept/book-2/unit-02/lesson-025">回看本课</a></p><h2 id="lesson-26-·-一般现在时与习惯" tabindex="-1">Lesson 26 · 一般现在时与习惯 <a class="header-anchor" href="#lesson-26-·-一般现在时与习惯" aria-label="Permalink to &quot;Lesson 26 · 一般现在时与习惯 {#lesson-26-·-一般现在时与习惯}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> My sister likes paintings with strong colours.</p><h3 id="练习-1-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-1" aria-label="Permalink to &quot;练习 1 {#练习-1-1}&quot;">​</a></h3><p>填 like：My sister ___ bright colours.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> likes</p><p><strong>解析：</strong> 一般现在时第三人称单数。</p></details><p><strong>表达迁移：</strong> 描述自己偏爱的艺术风格，再描述今天正在观看的一件不同作品。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>My sister likes paintings with strong colours. Today she is studying a black-and-white drawing. She says its simple lines are beautiful.</p><p>第一句的组织方式：likes 表稳定偏好，paintings 是泛指复数，with strong colours 为后置修饰语。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：She is liking this style 在一般偏好语境下不自然；常用 She likes this style。</p></details><p><a href="/life/english/new-concept/book-2/unit-02/lesson-026">回看本课</a></p><h2 id="lesson-27-·-过去完成时与先后关系" tabindex="-1">Lesson 27 · 过去完成时与先后关系 <a class="header-anchor" href="#lesson-27-·-过去完成时与先后关系" aria-label="Permalink to &quot;Lesson 27 · 过去完成时与先后关系 {#lesson-27-·-过去完成时与先后关系}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> We had covered the bags before the rain started.</p><h3 id="练习-1-2" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-2" aria-label="Permalink to &quot;练习 1 {#练习-1-2}&quot;">​</a></h3><p>填 cover：We had ___ the bags before it rained.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> covered</p><p><strong>解析：</strong> 过去完成时要求 had 加过去分词。</p></details><p><strong>表达迁移：</strong> 用四个事件描述露营遇雨，其中一件用过去完成时回顾。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>We had covered the bags before the rain started. Water still entered through the tent door. We moved to a nearby shelter at dawn.</p><p>第一句的组织方式：had covered 标记较早动作，before 从句 started 给出过去参照点；bags 是受保护的物品。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：had went 错误；had 后用过去分词 gone，不能用过去式 went。</p></details><p><a href="/life/english/new-concept/book-2/unit-02/lesson-027">回看本课</a></p><h2 id="lesson-28-·-动名词与动词搭配" tabindex="-1">Lesson 28 · 动名词与动词搭配 <a class="header-anchor" href="#lesson-28-·-动名词与动词搭配" aria-label="Permalink to &quot;Lesson 28 · 动名词与动词搭配 {#lesson-28-·-动名词与动词搭配}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Parking beside this gate blocks the entrance.</p><h3 id="练习-1-3" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-3" aria-label="Permalink to &quot;练习 1 {#练习-1-3}&quot;">​</a></h3><p>填 block：Parking here ___ the entrance.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> blocks</p><p><strong>解析：</strong> 动名词短语主语按单数处理。</p></details><p><strong>表达迁移：</strong> 为一个入口写两句告示，再加一句解释通行需求。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Parking beside this gate blocks the entrance. Delivery vans need room to turn. Visitors can use the public car park nearby.</p><p>第一句的组织方式：Parking beside this gate 是动名词短语作主语，整体视为单数，谓语用 blocks。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：Parking ... block 缺少第三人称单数词尾；一个动名词短语通常按单数看待。</p></details><p><a href="/life/english/new-concept/book-2/unit-02/lesson-028">回看本课</a></p><h2 id="lesson-29-·-现在完成时与过去时间" tabindex="-1">Lesson 29 · 现在完成时与过去时间 <a class="header-anchor" href="#lesson-29-·-现在完成时与过去时间" aria-label="Permalink to &quot;Lesson 29 · 现在完成时与过去时间 {#lesson-29-·-现在完成时与过去时间}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The small plane has carried a hundred passengers this week.</p><h3 id="练习-1-4" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-4" aria-label="Permalink to &quot;练习 1 {#练习-1-4}&quot;">​</a></h3><p>填 carry 的过去分词：The plane has ___ many passengers.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> carried</p><p><strong>解析：</strong> 辅音字母加 y 结尾变 y 为 i 再加 -ed。</p></details><p><strong>表达迁移：</strong> 介绍一个特别的交通服务，写累计成果、今天情况与下一步安排。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The small plane has carried a hundred passengers this week. Today the wind is too strong. The pilot has cancelled the afternoon flights.</p><p>第一句的组织方式：has carried 是现在完成时，a hundred passengers 为累计宾语，this week 连接过去活动与现在。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：has flew 错误，fly 的过去分词是 flown；本例 carry 的过去分词是 carried。</p></details><p><a href="/life/english/new-concept/book-2/unit-02/lesson-029">回看本课</a></p><h2 id="lesson-30-·-冠词与可数性" tabindex="-1">Lesson 30 · 冠词与可数性 <a class="header-anchor" href="#lesson-30-·-冠词与可数性" aria-label="Permalink to &quot;Lesson 30 · 冠词与可数性 {#lesson-30-·-冠词与可数性}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> A ball landed in the river beside our picnic spot.</p><h3 id="练习-1-5" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-5" aria-label="Permalink to &quot;练习 1 {#练习-1-5}&quot;">​</a></h3><p>填 a/the：A ball landed nearby. ___ ball was blue.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The</p><p><strong>解析：</strong> 第二次提及同一对象用定冠词。</p></details><p><strong>表达迁移：</strong> 讲述一个物品掉进水中的小意外，准确使用 a、the、into。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>A ball landed in the river beside our picnic spot. The ball floated towards a bridge. Its owner borrowed a long stick to reach it.</p><p>第一句的组织方式：A ball 首次引入对象，the river 是场景内可识别的河流，beside 短语修饰位置。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：on the river 通常表示在河面上，into the river 强调从外面进入水中。</p></details><p><a href="/life/english/new-concept/book-2/unit-02/lesson-030">回看本课</a></p><h2 id="lesson-31-·-一般现在时与习惯" tabindex="-1">Lesson 31 · 一般现在时与习惯 <a class="header-anchor" href="#lesson-31-·-一般现在时与习惯" aria-label="Permalink to &quot;Lesson 31 · 一般现在时与习惯 {#lesson-31-·-一般现在时与习惯}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Mina used to repair bicycles in her parents&#39; garage.</p><h3 id="练习-1-6" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-6" aria-label="Permalink to &quot;练习 1 {#练习-1-6}&quot;">​</a></h3><p>选 repair/repairing：Mina used to ___ bicycles.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> repair</p><p><strong>解析：</strong> used to 表过去习惯时接原形。</p></details><p><strong>表达迁移：</strong> 写一段小事业的发展，包含过去起点、现在规模和保留的习惯。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Mina used to repair bicycles in her parents&#39; garage. Now she runs a shop with three employees. She still repairs the oldest bicycles herself.</p><p>第一句的组织方式：used to 加原形 repair 表过去习惯，in 后为地点，parents&#39; 是复数所有格。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：used to repairing 把过去习惯与 be used to doing 混淆；此处应为 used to repair。</p></details><p><a href="/life/english/new-concept/book-2/unit-02/lesson-031">回看本课</a></p><h2 id="lesson-32-·-被动语态与信息重点" tabindex="-1">Lesson 32 · 被动语态与信息重点 <a class="header-anchor" href="#lesson-32-·-被动语态与信息重点" aria-label="Permalink to &quot;Lesson 32 · 被动语态与信息重点 {#lesson-32-·-被动语态与信息重点}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The missing receipt has been found behind the counter.</p><h3 id="练习-1-7" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-7" aria-label="Permalink to &quot;练习 1 {#练习-1-7}&quot;">​</a></h3><p>补全：The receipt has ___ found.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> been</p><p><strong>解析：</strong> 完成时被动为 has/have been done。</p></details><p><strong>表达迁移：</strong> 描述一次退货流程，包含找到凭证、核查和结果。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The missing receipt has been found behind the counter. The assistant checked the date. The customer then received a refund.</p><p>第一句的组织方式：receipt 是单数承受者，has been found 为完成时被动；behind the counter 说明发现地点。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：has found the receipt 是主动；receipt has found 缺少合理宾语且让收据成为发现者。</p></details><p><a href="/life/english/new-concept/book-2/unit-02/lesson-032">回看本课</a></p><h2 id="lesson-33-·-过去完成时与先后关系" tabindex="-1">Lesson 33 · 过去完成时与先后关系 <a class="header-anchor" href="#lesson-33-·-过去完成时与先后关系" aria-label="Permalink to &quot;Lesson 33 · 过去完成时与先后关系 {#lesson-33-·-过去完成时与先后关系}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> By the time we reached the shore, we had lost our map.</p><h3 id="练习-1-8" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-8" aria-label="Permalink to &quot;练习 1 {#练习-1-8}&quot;">​</a></h3><p>填 lose：We had ___ our map before we reached the shore.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> lost</p><p><strong>解析：</strong> 过去完成时用过去分词 lost。</p></details><p><strong>表达迁移：</strong> 按四个时间点写脱困经历，明确哪个困难发生在更早阶段。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>By the time we reached the shore, we had lost our map. A light appeared beyond the rocks. We followed it to a small harbour.</p><p>第一句的组织方式：By the time 从句 reached 建立过去参照点，主句 had lost 回顾更早事件，our map 是宾语。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：had lost 不表示此后才丢；它把丢地图放在到岸之前。</p></details><p><a href="/life/english/new-concept/book-2/unit-02/lesson-033">回看本课</a></p>',79)])])}const g=s(o,[["render",n]]);export{u as __pageData,g as default};
